'use server'

import { revalidatePath } from 'next/cache'
import fs from 'fs/promises'
import path from 'path'

const dbPath = path.join(process.cwd(), 'db.json')

export async function toggleNotifications() {
  const file = await fs.readFile(dbPath, 'utf8')
  const data = JSON.parse(file)

  data.notificationsEnabled = !data.notificationsEnabled

  await fs.writeFile(dbPath, JSON.stringify(data, null, 2))

  revalidatePath('/')
}

import { toggleNotifications } from './actions'
import fs from 'fs/promises'
import path from 'path'

const dbPath = path.join(process.cwd(), 'db.json')

async function getNotificationStatus() {
  try {
    const file = await fs.readFile(dbPath, 'utf8')
    return JSON.parse(file).notificationsEnabled
  } catch (error) {
    // If file doesn't exist or is empty, default to false
    return false
  }
}

export default async function Home() {
  const isEnabled = await getNotificationStatus()

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Settings</h1>
      <p>Notifications are currently: <strong>{isEnabled ? 'ON' : 'OFF'}</strong></p>

      <form action={toggleNotifications}>
        <button type="submit" style={{ padding: '0.5rem 1rem', marginTop: '1rem' }}>
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}
